SELECT


WHERE c.article_id = #{articleId}
  AND c.parent_id IS NULL
  AND c.deleted = 0
ORDER BY c.create_date_time ASC, c.id ASC
LIMIT #{offset}, #{size}

SELECT article_id AS id, CAST(COUNT(*) AS SIGNED) AS total FROM article_comment WHERE deleted = 0 AND parent_id IS NULL AND article_id IN
#{id}
GROUP BY article_id
